// Work conversations, linked materials and colleagues' contributions.
const legacyRender=render;
let conversationTab='All conversations',conversationSearch='',threadOpen=false;
let discussionReplies=load('wwk-discussion-replies',[]),localRequests=load('wwk-requests',[]);
const mainPost={id:'maya-study',author:'maya',status:'Open for input',topic:'Patient experience',title:'Would patients know which instructions to follow before their appointment?',intro:'Hi, I’m Maya, a designer new to Aster. I’m reviewing how patients find the information for their appointment. Could you take a look at the portal and our study plan before we run the next research sessions?',need:'Feedback on the portal and study tasks · Relevant experiences from your work',replies:5};
const otherPosts=[
 {id:'confirmation',author:'christine',status:'Open for input',topic:'Patient experience',title:'What helps someone recognize an appointment confirmation?',intro:'Hi, I’m Christine from patient services. A confirmation may say “First consultation” while a caller describes it as “my first appointment.” I’m reviewing the message with our content team. What has helped people recognize the same service across different channels?',need:'Content examples · Accessibility perspectives · Service terminology',replies:5},
 {id:'handover-work',author:'jonas',status:'Open for input',topic:'Team learning',title:'What context do you wish you had when taking over a project?',intro:'Hi, I’m Jonas from engineering. Another team found our final portal design, but not the reasons behind it. I’m updating our handover template so someone can understand the decision—and know when to question it. What would your team need?',need:'Handover experiences · Decision ownership · Changes in constraints',replies:5}
];
const threadDialog=document.createElement('dialog');threadDialog.id='materials-dialog';document.body.appendChild(threadDialog);
const requestDialog=document.createElement('dialog');requestDialog.id='request-dialog';
requestDialog.innerHTML=`<form id="request-form"><div class="dialog-top"><span class="eyebrow">OPEN YOUR WORK TO OTHER PERSPECTIVES</span><button type="button" class="icon-button" data-talk="close-request" aria-label="Close new conversation">×</button></div><h2>What are you working on?</h2><p class="muted">Give colleagues enough context to decide how they can help.</p><label>A clear question<input name="title" required placeholder="What would you like another perspective on?"></label><label>Introduce the work and why it matters<textarea name="context" required placeholder="Hi, I’m working on… It affects… We noticed…"></textarea></label><label>What input would help?<textarea name="ask" required placeholder="What can colleagues still influence? What experience would be useful?"></textarea></label><label>Link to work people can review (optional)<input name="link" type="url" placeholder="https://…"></label><p class="form-note">Include the work people can review and explain what is still open to change.</p><button class="primary" type="submit">Start conversation ↗</button></form>`;document.body.appendChild(requestDialog);
function localReplies(id){return discussionReplies.filter(r=>(r.post||'maya-study')===id)}
function contributionCount(p){return p.replies+localReplies(p.id).length}
function materialLinks(){return `<div class="attachment-preview"><button data-material="portal">▧ <span>Appointment preparation<small>Live portal + design review · v0.4</small></span> ↗</button><button data-material="tasks">▤ <span>Usability study plan<small>Draft v0.2 · Maya Chen · 29 Oct</small></span> ↗</button></div>`}
function postCard(p){return `<article class="post-card"><div class="post-byline">${avatar(p.author)}<div><strong>${people[p.author].name}</strong><small>${people[p.author].role} · ${p.author==='maya'?'Patient portal':'Across Aster'}</small></div><span class="post-time">${p.id==='maya-study'?'Today · 09:15':'Yesterday'}</span></div><div class="post-meta"><span class="badge perspective">${escape(p.status)}</span><span>${escape(p.topic)}</span></div><h2><button data-thread="${p.id}">${escape(p.title)}</button></h2><p>${escape(p.intro)}</p><div class="post-ask"><span>LOOKING FOR</span>${escape(p.need)}</div>${p.id==='maya-study'?materialLinks():''}<div class="post-bottom"><button class="text-button" data-thread="${p.id}">◌ ${contributionCount(p)} contributions · Join the conversation →</button>${p.id==='maya-study'?'<span class="small-update">✓ Maya shared an update</span>':''}</div></article>`}
function conversationHome(){threadOpen=false;$('#crumb').textContent='Open conversations';$('#content').innerHTML=`<div class="page-heading"><div><span class="eyebrow">GOOD WORK STARTS WITH ANOTHER PERSPECTIVE</span><h1>What are you working on?</h1><p>Open a question. Share your experience. Help a colleague see something differently.</p></div><button class="primary" data-talk="new">Start a conversation <span>＋</span></button></div><div class="conversation-layout"><section><div class="search"><span>⌕</span><input id="conversation-search" aria-label="Search conversations" placeholder="Find a question, topic or colleague…" value="${escape(conversationSearch)}"></div><div class="filters">${['All conversations','Open for input','Updates'].map(f=>`<button class="filter ${conversationTab===f?'active':''}" data-conversation-filter="${f}">${f}</button>`).join('')}</div><div id="posts"></div></section><div class="conversation-aside"><div class="welcome-panel"><span class="spark">✳</span><h3>Your experience might <span class="keep-together">help another team.</span></h3><p>You don’t need to know everyone—or have the final answer. A question, an example or a different way of looking can help.</p><div class="divider"></div><span class="eyebrow">YOUR CURRENT WORK</span><h4>Appointment preparation</h4><p>Review the portal, gather colleagues’ perspectives and prepare your next research sessions.</p><button class="text-button" data-thread="maya-study">View my conversation ↗</button></div><div class="small-panel"><h4>Bring an experience into the conversation</h4><p>Find something a colleague has already tried, learned or questioned.</p><button class="text-button" data-nav="experiences">Explore shared experiences ↗</button></div></div></div>`;drawPosts()}
function drawPosts(){const posts=[mainPost,...localRequests,...otherPosts].filter(p=>(conversationTab!=='Open for input'||p.status==='Open for input')&&(conversationTab!=='Updates'||p.id==='maya-study')&&(p.title+' '+p.intro+' '+people[p.author].name).toLowerCase().includes(conversationSearch.toLowerCase()));$('#posts').innerHTML=posts.length?posts.map(postCard).join(''):'<div class="empty">No conversations match. Try another search or filter.</div>'}
function personLine(key,extra=''){return `${avatar(key)}<div><strong>${people[key].name}</strong><small>${people[key].role}${extra?' · '+extra:''}</small></div>`}
function sampleReply(key,text,extra='',nested=''){return `<article class="reply"><div class="post-byline">${personLine(key,extra)}</div><p>${text}</p>${nested}</article>`}
function authorFollowup(key,text){return `<div class="nested-reply"><div class="post-byline">${personLine(key,'Author')}</div><p>${text}</p></div>`}
function mainContext(){return `<h3>The work</h3><p>The portal’s preparation page combines information for first consultations and follow-up appointments. Patients have to work out which sections apply to them. I’m planning sessions to observe how they find and interpret the information for their own visit.</p><h3>What we already know</h3><p>Christine’s team receives calls asking which instructions apply. In Alex’s earlier study, some participants understood the wording but could not identify the section for their appointment. I’d like to test finding the right information separately from understanding the words.</p><h3>Work to review</h3>${materialLinks()}<h3>Where another perspective would help</h3><ul><li>Does the appointment context make sense outside the product team?</li><li>Have you seen the same issue in another service?</li><li>Are our tasks realistic, or do they tell participants where to look?</li></ul><div class="context-box"><strong>Open for review</strong><br>The page structure, appointment names and study starting point can change. Nina will review the appointment scenario before the sessions; medical preparation requirements remain with the clinical team.</div><p>I’ll post the revised plan here so you can see what we took forward. — Maya</p>`}
function supportingContext(p){
 if(p.id==='confirmation')return `<h3>What we’re reviewing</h3><p>The email subject, appointment name and destination page currently use slightly different descriptions. Before we change the copy, I want to understand what helps people connect those steps.</p><div class="context-box"><strong>Current message</strong><br>Subject: Your appointment at Aster<br>“Your first consultation is confirmed for 12 November at 10:00. Please review the preparation information in your patient portal.”<br><br><strong>Question for colleagues</strong><br>Would you recognize the appointment from the subject alone? What words would you carry through to the portal?</div><div class="attachment-preview"><button data-material="confirmation"><span>Appointment-confirmation email<small>Content review · Christine + Elena</small></span> ↗</button></div><h3>What can change</h3><p>The subject, opening sentence and link label. We need to retain the appointment type and date, and avoid adding personal information to the subject line.</p>`;
 if(p.id==='handover-work')return `<h3>Why I’m revisiting this</h3><p>The appointment page stayed in place because its original maintenance constraint was treated as permanent. Our booking data has since changed. A useful handover should make those assumptions visible to the next team.</p><div class="context-box"><strong>Decision record · draft v0.3</strong><br>1. Decision and current owner<br>2. Why we chose it and alternatives considered<br>3. Evidence and constraints at the time<br>4. What would make us revisit it<br>5. Links to the design, code and research</div><div class="attachment-preview"><button data-material="handover"><span>Portal decision record<small>Jonas Keller · Open for review</small></span> ↗</button></div><h3>What would help?</h3><p>Think about the last time you picked up someone else’s work. Which question could the document answer before you needed to arrange a meeting?</p>`;
 return `<h3>What input would help?</h3><p>${escape(p.need)}</p>${p.link?`<a class="inline-link" href="${escape(p.link)}" target="_blank" rel="noopener noreferrer">Review linked work ↗</a>`:''}`;
}
function seededDiscussion(id){
 if(id==='maya-study')return sampleReply('christine','Some callers read the whole page and then ask us to confirm which section is theirs. Could participants start with the message confirming their appointment? That would let us see whether they recognize the appointment name and find the right link.','Today · 09:42',authorFollowup('maya','Good point. My draft starts on the preparation page, so it skips how people get there. Could we review the words callers use before we write the scenario?'))+sampleReply('alex','In the earlier study, some people could explain the instructions but still did not know which ones applied. It may help to test finding the right information separately from understanding the words.','Today · 10:08',`<button class="linked-experience" data-open="instructions"><span class="badge">Connected experience</span><strong>Patients understood the words, but weren’t sure which instructions applied.</strong><span>Read the study account ↗</span></button>`)+sampleReply('jonas','We originally combined the instructions so staff would not need to maintain several pages. The portal can now identify the booked appointment type, so we can revisit that decision. I can check the content-routing options with you.','Today · 10:35')+`<section class="outcome-update"><span class="eyebrow">MAYA’S UPDATE · TODAY, 14:20</span><h3>The study will start with the appointment confirmation.</h3><p>I’ve changed the starting point and removed the page labels from the task. In my previous design work, goal-based tasks helped us see how people found their own route rather than following our wording.</p><p>Christine will check the scenario against patient-service conversations. Alex’s study helps us separate relevance from readability. Jonas will review whether appointment-specific content is feasible.</p><button class="text-button" data-material="revised">Read the revised study plan · v0.3 ↗</button><small>Next: scenario review with Nina, then moderated sessions.</small></section>`;
 if(id==='confirmation')return sampleReply('elena','I’d lead with the service and date: “Your first consultation · 12 November”. Then use “Prepare for your first consultation” as the link label and the page heading. That gives people a consistent phrase to follow.','Yesterday · 11:10',authorFollowup('christine','That would also give our team a phrase to use on calls. I’ll compare it with the appointment names in the booking system before we settle the copy.'))+sampleReply('luca','During clinic onboarding, reception staff often say “first appointment” rather than “consultation”. Could the opening sentence use both once—“your first appointment (initial consultation)”—and then keep the wording consistent?','Yesterday · 13:25')+sampleReply('samir','Make the link describe the destination even when it is read on its own. “Click here” or “Read more” loses its context in a screen-reader links list. I’m happy to review the message when you have the next draft.','Today · 08:50',authorFollowup('christine','Thanks. Elena and I will bring the revised message to the portal study rather than review the email in isolation.'));
 if(id==='handover-work')return sampleReply('maya','As someone new to the team, I’d add one sentence on who is affected and a link to the research that informed the decision. I can read what we chose, but I also need to know which customer or staff problem it was meant to solve.','Yesterday · 15:05',authorFollowup('jonas','Added “who this affects” beside the decision, and a direct research link. That is the context I was taking for granted.'))+sampleReply('nina','Could we distinguish a clinical requirement from an operational choice? They need different owners. A team should be able to see which changes need clinical review and which can be explored with engineering or content.','Today · 09:20')+sampleReply('ines','A “revisit when” field would help more than a review date alone. For example: appointment-type data becomes available, the content owner changes, or research contradicts an assumption. Then record what changed when the decision is reopened.','Today · 11:40',authorFollowup('jonas','I’ve separated requirements from trade-offs and added a revisit trigger. I’ll use this structure for the appointment-preparation decision first, then ask the next team whether it answers their questions.'));
 return '';
}
function openThread(id){const p=[mainPost,...otherPosts,...localRequests].find(p=>p.id===id);if(!p)return;threadOpen=true;$('#crumb').textContent='Conversation';$('#content').innerHTML=`<button class="back-link" data-talk="back">← All conversations</button><div class="thread-layout"><article class="thread-main"><div class="post-byline">${personLine(p.author,p.author==='maya'?'Author':'')}<span class="post-time">${p.id==='maya-study'?'Today · 09:15':'Yesterday'}</span></div><div class="post-meta"><span class="badge perspective">${escape(p.status)}</span><span>${escape(p.topic)}</span></div><h1>${escape(p.title)}</h1><div class="thread-copy"><p>${escape(p.intro)}</p>${p.id==='maya-study'?mainContext():supportingContext(p)}</div><div class="discussion-heading"><h2>The conversation</h2><span>${contributionCount(p)} contributions</span></div><div class="discussion">${seededDiscussion(p.id)}${localReplies(id).map(r=>sampleReply('maya',escape(r.text),'Your contribution',r.experience?`<button class="linked-experience" data-open="${escape(r.experience)}"><strong>${escape(entries.find(e=>e.id===r.experience)?.title)}</strong><span>Connected experience ↗</span></button>`:'')).join('')}</div><form id="reply-form" data-post="${p.id}" class="reply-composer"><div class="post-byline">${personLine('maya','You')}</div><label>Add a perspective<textarea name="reply" required placeholder="Share an experience, ask a question, or explain what you see differently…"></textarea></label><label class="attach-label">Connect a previous experience (optional)<select name="experience"><option value="">No experience attached</option>${entries.map(e=>`<option value="${e.id}">${escape(e.title)}</option>`).join('')}</select></label><div class="composer-bottom"><small>Replying as Maya Chen</small><button class="primary" type="submit">Add to conversation ↗</button></div></form></article><aside class="thread-context"><span class="eyebrow">ABOUT THIS WORK</span><h3>${p.id==='handover-work'?'Project handovers':p.id==='confirmation'?'Appointment messages':'Patient portal'}</h3><p>${p.id==='handover-work'?'Keeping decisions useful when work changes hands.':'Helping patients recognize their appointment and find the right information.'}</p><dl><dt>Stage</dt><dd>Open for review</dd><dt>Looking for</dt><dd>${escape(p.need)}</dd></dl><div class="divider"></div><h4>Different experience is welcome</h4><p>You can contribute without joining the project or committing to mentoring.</p><button class="text-button" data-nav="people">Meet colleagues ↗</button></aside></div>`;window.scrollTo(0,0)}
function docHeader(label,title,owner,version){return `<div class="work-doc-header"><div><span class="eyebrow">${label}</span><h2>${title}</h2></div><div class="work-doc-owner">${avatar(owner)}<span>${people[owner].name}<small>${version}</small></span></div></div>`}
function researchDocument(revised){return `${docHeader('PATIENT PORTAL / RESEARCH','Appointment preparation · usability study','maya',revised?'v0.3 · Updated today, 14:20':'v0.2 · 29 Oct 2026')}<div class="doc-facts"><span><b>Status</b> ${revised?'Scenario review':'Team review'}</span><span><b>Format</b> Moderated · 30 minutes</span><span><b>Planned sessions</b> 6</span></div><section class="doc-section"><h3>What we need to learn</h3><p>Can patients find the preparation information for their appointment and explain what they would do next?</p></section><section class="doc-section"><h3>Participant context</h3><p>Adults preparing for a first consultation, with a mix of familiarity with online appointment services. Use the same appointment scenario across sessions and record where assistance is needed.</p></section><section class="doc-section"><h3>Starting point</h3><p>${revised?'Give participants the appointment-confirmation message. Let them decide how to reach the relevant preparation information.':'Open the preparation page before the session. Ask participants to imagine they have booked a first consultation.'}</p></section><section class="doc-section"><h3>Session tasks</h3><ol class="study-task-list"><li><b>${revised?'Find what you need before your visit':'Find your appointment instructions'}</b><p>${revised?'“Imagine your first appointment is next week. Using this confirmation message, show us how you would find out what to do before your visit.”':'“Open the preparation page and find the section for your appointment.”'}</p><small>${revised?'Observe the route, terminology and information selected. Do not name the page or buttons.':'Check whether the wording gives away the intended route.'}</small></li><li><b>Explain the next step</b><p>“What would you do to get ready? Is there anything you would still need to check?”</p></li><li><b>Resolve an uncertainty</b><p>“If something didn’t match your appointment, what would you do?”</p></li></ol></section><section class="doc-section"><h3>What we’ll record</h3><p>Starting expectations · route taken · sections selected · uncertainty · requests for help. Separate finding the right information from understanding the wording.</p></section><section class="doc-section doc-decision"><h3>${revised?'Changes after the conversation':'Open review questions'}</h3><p>${revised?'Christine: start from the confirmation. Alex: distinguish relevance from readability. Jonas: check appointment-specific content. Maya: use a goal-based task rather than interface labels.':'Does the scenario sound like a real appointment? Are we missing the journey into the page? Which terms would participants recognize?'}</p><p><b>Next:</b> Nina reviews the scenario; Maya prepares the session materials. No sessions have been run for this plan.</p></section>`}
function confirmationDocument(){return `${docHeader('PATIENT SERVICES / CONTENT REVIEW','Appointment-confirmation email','christine','v0.2 · Review with Elena')}<div class="doc-facts"><span><b>Channel</b> Email</span><span><b>Trigger</b> Appointment confirmed</span><span><b>Owner</b> Patient services</span></div><div class="email-review"><div class="email-envelope"><p><b>From</b> Aster appointments</p><p><b>Subject</b> Your first consultation · 12 November</p></div><div class="email-message"><span class="portal-wordmark">aster<span>health</span></span><h2>Your appointment is confirmed.</h2><p>Your first appointment (initial consultation) is booked. You can find the details and preparation information in your patient portal.</p><div class="portal-visit"><span>12 NOV</span><div><b>First consultation</b><p>Thursday, 12 November · 10:00<br>Aster outpatient clinic · Reception A</p></div></div><button class="portal-primary" data-material="portal">Prepare for your first consultation →</button><p>Need to change something? Contact patient services using the details in your portal.</p></div></div><section class="doc-section"><h3>Review notes</h3><p>Elena: keep the appointment name consistent across the subject, link and destination. Luca: check the words reception teams use. Samir: make the link meaningful outside its surrounding paragraph.</p></section>`}
function handoverDocument(){return `${docHeader('ENGINEERING / DECISION RECORD','Appointment-specific preparation content','jonas','ADR-014 · Review in progress')}<div class="doc-facts"><span><b>Decision owner</b> Portal engineering</span><span><b>Content owner</b> Patient services</span></div><section class="doc-section"><h3>Who this affects</h3><p>Patients preparing for different appointment types, staff maintaining preparation information, and teams building portal journeys.</p></section><section class="doc-section"><h3>Original decision</h3><p>Maintain one preparation page for first and follow-up appointments. At the time, the portal did not expose the booked appointment type to the content layer.</p></section><section class="doc-section"><h3>Trade-off</h3><p>One source reduced duplicate content maintenance, but patients needed to identify the section that applied to their appointment.</p></section><section class="doc-section"><h3>What has changed</h3><p>The booking service now returns the appointment type. We can investigate routing relevant content while retaining one owned content source.</p><button class="text-button" data-open="constraints">Read the engineering context ↗</button></section><section class="doc-section"><h3>Requirements and review owners</h3><p><b>Clinical content:</b> reviewed by the clinical product team.<br><b>Content updates:</b> owned by patient services.<br><b>Routing and fallback:</b> reviewed by engineering with accessibility input.</p></section><section class="doc-section doc-decision"><h3>Revisit when</h3><p>Appointment data changes, content ownership changes, or research shows patients cannot identify the right information. Link the evidence, record the changed assumption and name the next decision owner.</p></section>`}
let activePortalVersion='before',portalVisit='first';
function showMaterial(kind){const portal=kind==='portal';threadDialog.classList.toggle('material-wide',portal);threadDialog.innerHTML=`<div class="dialog-inner material-document"><div class="dialog-top"><span class="eyebrow">${portal?'PATIENT PORTAL / DESIGN REVIEW':'PROJECT MATERIALS'}</span><button class="icon-button" data-talk="close-material" aria-label="Close material">×</button></div>${portal?`<div class="work-doc-header"><div><h2>Appointment preparation</h2><p class="muted">Review the live journey alongside the appointment-specific flow.</p></div><span class="review-status">Maya Chen · Design review</span></div><div class="material-tabs" role="group" aria-label="Portal version"><button class="filter active" data-page-version="before">Live portal · v2.8</button><button class="filter" data-page-version="proposed">Design review · v0.4</button></div><div id="portal-preview"></div>`:kind==='confirmation'?confirmationDocument():kind==='handover'?handoverDocument():researchDocument(kind==='revised')}</div>`;if(!threadDialog.open)threadDialog.showModal();threadDialog.scrollTop=0;if(portal){portalVisit='first';drawPortal('before')}}
function drawPortal(version){activePortalVersion=version;const first=portalVisit==='first';$('#portal-preview').innerHTML=`<div class="patient-workspace"><div class="portal-topbar"><span class="portal-wordmark">aster<span>health</span></span><div class="portal-navigation"><span>Overview</span><span class="selected">Appointments</span><span>Messages</span></div><span class="portal-security">Your patient portal</span></div><div class="portal-body"><p class="portal-crumb">Appointments / ${version==='before'?'Preparation':first?'First consultation':'Follow-up appointment'}</p><div class="portal-title-row"><div><span class="eyebrow">YOUR UPCOMING VISIT</span><h2>${version==='before'?'Prepare for your appointment':first?'Prepare for your first consultation':'Prepare for your follow-up'}</h2><p>Find the information you need before you arrive.</p></div><span class="portal-booked">Confirmed</span></div>${version==='proposed'?`<div class="portal-flow-controls" role="group" aria-label="Appointment type"><span>View appointment:</span><button class="${first?'selected':''}" data-portal-visit="first">First consultation</button><button class="${!first?'selected':''}" data-portal-visit="followup">Follow-up</button></div>`:''}<div class="portal-content-grid"><section><div class="portal-visit"><span>12<br>NOV</span><div><b>${version==='before'||first?'First consultation':'Follow-up appointment'}</b><p>Thursday, 12 November · 10:00–10:45<br>Aster outpatient clinic · Reception A</p></div></div>${version==='before'?`<p class="portal-intro">Preparation depends on the appointment you have booked. Check your confirmation and read the relevant section below.</p><section class="portal-section"><h3>Before any appointment</h3><p>Check the time and location in your confirmation. Have your appointment confirmation available and make a note of the questions you would like to discuss.</p></section><section class="portal-section"><h3>First consultations</h3><p>Review the welcome information sent with your confirmation. If you need support with access, language or getting to reception, contact patient services before your visit.</p></section><section class="portal-section"><h3>Follow-up appointments</h3><p>Review the questions and next steps you agreed with your care team at your previous visit. Check any separate messages from the team.</p></section>`:`<div class="portal-relevance">These details are for your ${first?'first consultation':'follow-up appointment'} on 12 November.</div><section class="portal-section"><h3>Your preparation checklist</h3><ul class="portal-checklist"><li>Check the appointment time and reception location.</li><li>Have your appointment confirmation available.</li><li>${first?'Review the welcome information in your confirmation.':'Review the questions and next steps from your previous visit.'}</li><li>Write down any questions you want to discuss.</li></ul><p class="portal-content-note">If your care team has sent separate preparation instructions, check those messages before your visit.</p></section><details class="portal-details"><summary>This doesn’t match my appointment</summary><p>Check the appointment name and date in your confirmation. Contact patient services if the details differ, so the team can check your booking.</p></details>`}<details class="portal-details"><summary>Where do I go when I arrive?</summary><p>Go to Reception A at the outpatient clinic. Show your appointment confirmation so reception can direct you to the right team.</p></details><details class="portal-details"><summary>I need help with access or language</summary><p>Let patient services know what support you need before your visit. The team can help you plan your arrival and check available support.</p></details></section><aside class="portal-support"><span class="eyebrow">BEFORE YOUR VISIT</span><h3>A question about your appointment?</h3><p>Patient services can help with booking details, finding reception and access support.</p><button class="portal-contact-button" data-portal-contact>Contact patient services</button><div id="portal-contact-details" hidden><b>Patient services</b><p>Send a message through your appointment-confirmation email, or use the contact number provided with your booking.</p><small>For questions about your care, contact your care team.</small></div><div class="portal-support-divider"></div><h4>Keep your details together</h4><p>Use the appointment name and date from your confirmation when you contact us.</p></aside></div><footer class="portal-footer">Aster Health · Appointment information <span>Privacy · Accessibility</span></footer></div></div>`;document.querySelectorAll('[data-page-version]').forEach(b=>b.classList.toggle('active',b.dataset.pageVersion===version))}

function projectConversationSummary(){
  const ownReplies=discussionReplies.filter(r=>(r.post||'maya-study')==='maya-study');
  return `<section class="project-conversation" aria-labelledby="project-conversation-title"><div class="section-heading"><h2 id="project-conversation-title">My conversation</h2><span>Started by you · Maya Chen</span></div><article class="note-card"><div class="post-byline">${personLine('maya','Author')}<span class="badge perspective">Open for input</span></div><h3><button class="project-question" data-thread="maya-study">${escape(mainPost.title)}</button></h3><p>You asked colleagues to review the preparation page and draft study tasks.</p><div class="project-author-update"><span class="eyebrow">YOUR LATEST UPDATE</span><h4>Start the study with the appointment-confirmation message.</h4><p>You combined Christine’s service experience, Alex’s earlier study and Jonas’s technical context with your own goal-based research approach.</p><button class="text-button" data-material="revised">Read my revised study plan ↗</button></div>${ownReplies.length?`<div class="project-own-reply"><span class="eyebrow">YOUR LATEST REPLY</span><p>${escape(ownReplies[ownReplies.length-1].text)}</p></div>`:''}<div class="project-conversation-actions"><button class="text-button" data-thread="maya-study">View conversation & my replies →</button><span>${5+ownReplies.length} contributions</span></div></article>${localRequests.map(p=>`<article class="note-card"><span class="eyebrow">CONVERSATION STARTED BY YOU</span><h3><button class="project-question" data-thread="${escape(p.id)}">${escape(p.title)}</button></h3><p>${escape(p.intro)}</p><button class="text-button" data-thread="${escape(p.id)}">Open my conversation →</button></article>`).join('')}</section>`;
}

render=function(){document.querySelector('nav [data-nav="explore"]').innerHTML='<span>◌</span> Open conversations';if(!document.querySelector('nav [data-nav="experiences"]')){const n=document.createElement('button');n.dataset.nav='experiences';n.innerHTML='<span>◉</span> Shared experiences';document.querySelector('nav').insertBefore(n,document.querySelector('nav [data-nav="project"]'))}if(view==='explore'){document.querySelectorAll('nav [data-nav]').forEach(n=>n.classList.toggle('active',n.dataset.nav==='explore'));conversationHome()}else if(view==='experiences'){view='explore';legacyRender();view='experiences';$('#crumb').textContent='Shared experiences';document.querySelectorAll('nav [data-nav]').forEach(n=>n.classList.toggle('active',n.dataset.nav==='experiences'));$('#content .page-heading h1').textContent='Experience worth bringing into the conversation.';$('#content .page-heading p').textContent='Explore what colleagues have tried, learned and questioned.';$('.project-banner')?.remove();}else{legacyRender();if(view==='project'){$('.project-header').insertAdjacentHTML('afterend',projectConversationSummary())}}};
document.addEventListener('click',ev=>{const b=ev.target.closest('button');if(!b)return;if(b.dataset.thread)openThread(b.dataset.thread);if(b.dataset.material)showMaterial(b.dataset.material);if(b.dataset.pageVersion)drawPortal(b.dataset.pageVersion);if(b.dataset.conversationFilter){conversationTab=b.dataset.conversationFilter;conversationHome()}if(b.dataset.talk==='new')requestDialog.showModal();if(b.dataset.talk==='close-request')requestDialog.close();if(b.dataset.talk==='close-material')threadDialog.close();if(b.dataset.talk==='back')conversationHome();if(b.dataset.nav==='explore')window.scrollTo(0,0)});
document.addEventListener('input',ev=>{if(ev.target.id==='conversation-search'){conversationSearch=ev.target.value;drawPosts()}});
document.addEventListener('submit',ev=>{if(ev.target.id==='reply-form'){ev.preventDefault();const f=new FormData(ev.target),text=f.get('reply').trim();if(!text)return;const id=ev.target.dataset.post;discussionReplies.push({post:id,text,experience:f.get('experience')});localStorage.setItem('wwk-discussion-replies',JSON.stringify(discussionReplies));openThread(id);document.querySelector('.reply-composer').scrollIntoView({block:'center',behavior:'smooth'});toast('Your perspective was added to the conversation')}if(ev.target.id==='request-form'){ev.preventDefault();const f=new FormData(ev.target);if(!f.get('title').trim()||!f.get('context').trim()||!f.get('ask').trim())return;const raw=f.get('link').trim();const link=/^https?:\/\//i.test(raw)?raw:'';localRequests.unshift({id:'request-'+Date.now(),author:'maya',status:'Open for input',topic:'Across teams',title:f.get('title').trim(),intro:f.get('context').trim(),need:f.get('ask').trim(),link,replies:0});localStorage.setItem('wwk-requests',JSON.stringify(localRequests));requestDialog.close();ev.target.reset();view='explore';conversationTab='All conversations';conversationSearch='';render();toast('Conversation started')}});
threadDialog.addEventListener('click',e=>{if(e.target===threadDialog)threadDialog.close()});requestDialog.addEventListener('click',e=>{if(e.target===requestDialog)requestDialog.close()});
render();

document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.portalVisit){portalVisit=b.dataset.portalVisit;drawPortal(activePortalVersion);}if(b.hasAttribute('data-portal-contact')){const details=document.getElementById('portal-contact-details');details.hidden=!details.hidden;b.setAttribute('aria-expanded',String(!details.hidden));}});
